"""Querying and adjusting the privileges held by the current process."""

from .errors import WTokenError
from . import _winapi


def _open_token_for_query():
    """Open the current process token with TOKEN_QUERY access."""
    return _winapi.open_process_token(_winapi.TOKEN_QUERY)


def _open_token_for_adjust():
    """Open the current process token with TOKEN_ADJUST_PRIVILEGES | TOKEN_QUERY."""
    return _winapi.open_process_token(
        _winapi.TOKEN_ADJUST_PRIVILEGES | _winapi.TOKEN_QUERY
    )


def privileges():
    """Return ``{name: enabled}`` for every privilege the token holds.

    Each entry represents a privilege that the token **holds**; the boolean
    value is ``True`` only when that privilege is currently **enabled**.
    A privilege can be held but disabled, in which case it appears here
    with a value of ``False``.
    """
    if not _winapi.is_windows():
        raise WTokenError(
            "privilege enumeration requires Windows", kind="unsupported"
        )
    handle = _open_token_for_query()
    try:
        privs = _winapi.get_token_privileges(handle)
    finally:
        _winapi.close_handle(handle)

    result = {}
    for luid, attrs in privs:
        try:
            name = _winapi.lookup_privilege_name(luid)
        except WTokenError:
            # Skip privileges whose names cannot be resolved (shouldn't happen
            # on a healthy system, but be defensive).
            continue
        enabled = bool(attrs & _winapi.SE_PRIVILEGE_ENABLED)
        result[name] = enabled
    return result


def has_privilege(name):
    """Return ``True`` when the token holds ``name``, regardless of whether
    it is currently enabled."""
    if not name or not isinstance(name, str):
        return False
    if not _winapi.is_windows():
        return False
    try:
        table = privileges()
    except WTokenError:
        return False
    return name in table


def set_privilege(name, enabled=True):
    """Enable or disable a held privilege.

    Raises :class:`WTokenError` with ``kind="badarg"`` when *name* is empty,
    unknown, or not held by the token.  Raises with ``kind="os"`` when the
    underlying system call fails.
    """
    if not _winapi.is_windows():
        raise WTokenError(
            "privilege adjustment requires Windows", kind="unsupported"
        )
    if not name or not isinstance(name, str):
        raise WTokenError(
            "a non-empty privilege name is required",
            kind="badarg",
            privilege=name,
        )

    # Verify the token actually holds this privilege before attempting to
    # adjust it.  LookupPrivilegeValueW succeeds for any known privilege
    # name even if the token doesn't hold it, so we must cross-check.
    table = privileges()
    if name not in table:
        raise WTokenError(
            "the token does not hold privilege %r" % (name,),
            kind="badarg",
            privilege=name,
        )

    luid = _winapi.lookup_privilege_value(name)
    handle = _open_token_for_adjust()
    try:
        _winapi.adjust_token_privileges(handle, luid, bool(enabled))
    finally:
        _winapi.close_handle(handle)


def privilege_luid(name):
    """Return the LUID the system assigns to *name*.

    The returned object is a ctypes Structure with ``LowPart`` and
    ``HighPart`` fields.  It can also be compared and hashed via its
    numeric representation ``(HighPart << 32) | LowPart``.
    """
    if not _winapi.is_windows():
        raise WTokenError(
            "LUID lookup requires Windows", kind="unsupported"
        )
    if not name or not isinstance(name, str):
        raise WTokenError(
            "a non-empty privilege name is required",
            kind="badarg",
            privilege=name,
        )
    # LookupPrivilegeValueW will fail for truly unknown names; but it can
    # succeed for names the token doesn't hold.  That's fine – the LUID is
    # a system-wide constant for a given privilege name.
    return _winapi.lookup_privilege_value(name)


def privilege_name(luid):
    """Return the privilege name for a LUID.

    *luid* may be either a LUID structure (as returned by
    :func:`privilege_luid`) or an integer of the form
    ``(high << 32) | low``.
    """
    if not _winapi.is_windows():
        raise WTokenError(
            "privilege name lookup requires Windows", kind="unsupported"
        )
    if isinstance(luid, int):
        la = _winapi.LUID()
        la.LowPart = luid & 0xFFFFFFFF
        la.HighPart = (luid >> 32) & 0xFFFFFFFF
        luid = la
    elif isinstance(luid, _winapi.LUID):
        pass
    else:
        # Try treating as something with LowPart / HighPart
        try:
            low = int(luid.LowPart)
            high = int(luid.HighPart)
        except (AttributeError, TypeError, ValueError):
            raise WTokenError(
                "a privilege identifier must be a LUID or integer, got %r"
                % (luid,),
                kind="badarg",
            )
        la = _winapi.LUID()
        la.LowPart = low & 0xFFFFFFFF
        la.HighPart = high & 0xFFFFFFFF
        luid = la

    return _winapi.lookup_privilege_name(luid)

